from pathlib import Path
import json,pickle,hashlib,sys,time
import independent_reporting as point
D=Path(sys.argv[1]);cached=pickle.loads((D/'independent_prefix.pkl').read_bytes());raw=D/'trials.jsonl';assert cached['offset']==raw.stat().st_size and cached['accepted']>0
assert hashlib.sha256(raw.read_bytes()).hexdigest()==cached['raw_prefix_sha256'];s=cached['point'];header=json.loads((D/'header.jsonl').read_text());assert header==cached['header'];h={'FLRW':[1e-14]*3,'BI':[1.01e-14,.99e-14,1e-14],'EPS_HALF':[1.005e-14,.995e-14,1e-14]}[header['geometry']];summary=json.loads((D/'summary.json').read_text());assert s.time==cached['radiation'].time==summary['time_s']==1e13;assert summary['accepted']==cached['accepted'] and summary['rejected']==cached['rejected'];point.report(header,h,s,summary);offset=point.checkpoint(header,s,D/'checkpoint.dat',cached['accepted'],cached['rejected']);assert offset==raw.stat().st_size;residual=point.cumulative(header,s);assert max(residual)<=1e-12
for key,v in zip(['cumulative_n_residual','cumulative_u_residual'],residual):point.close(summary[key],v,1.,key)
result={'status':'WHOLE_HISTORY_COMPONENT_INDEPENDENT_PASS','trials':cached['accepted'],'runs':[{'run':D.name,'time_s':s.time,'accepted':cached['accepted'],'rejected':cached['rejected'],'maxima':cached['maxima'],'cumulative':residual,'raw_sha256':cached['raw_prefix_sha256']}],'production_evaluator_called':False,'scientific_admission':'HOLD','composed_validation':{'successful_trial_phase_source_hashes':cached['source_hashes'],'closeout_fix':'Guard representation binding at existing normalized1e-12 photon/energy scales, no scientific gate change','prior_proven_prefix_replayed':False,'source_changes':'checkpoint guard comparisons only; original v4 snapshot preserved'}};(D/'independent_history_receipt.json').write_text(json.dumps(result,indent=2)+'\n');print(json.dumps(result))
